import json
from pathlib import Path

def md(s): return {'cell_type':'markdown','metadata':{},'source':s.splitlines(True)}
def code(s): return {'cell_type':'code','execution_count':None,'metadata':{},'outputs':[],'source':s.splitlines(True)}

cells=[
md('''# CUSUM 누적 경보 검증\n\n기존 최적화 HGB 이진 분류 모델의 분당 확률을 사용해 CUSUM 경보를 검토합니다. 모델은 재학습하거나 교체하지 않습니다.\n\n핵심 질문은 작은 이상 점수가 쌓이면 독립 Test의 탐지가 빨라지는지, 같은 기준에서 정상 구간 오경보가 운영 가능한지입니다. 전체 정상 재생은 임계값 조정용이며 독립 성능 평가로 해석하지 않습니다.'''),
code('''from pathlib import Path\nimport json\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\nTEST=Path('data/modeling/test_binary_predictions_optimized.csv.gz')\nFULL=Path('data/modeling/continuous_replay_predictions.csv.gz')\ntest=pd.read_csv(TEST); full=pd.read_csv(FULL)\nprint(f'Test 이벤트 {test.sample_event_id.nunique()}개, 전체 재생 {len(full):,}행')\n'''),
md('''## 1. CUSUM은 무엇을 누적하나?\n\n분당 확률 p를 log-odds로 바꾸고 기준 확률 p₀를 뺀 증거량을 누적합니다.\n\n`Sₜ = max(0, Sₜ₋₁ + logit(pₜ) − logit(p₀))`\n\nS가 경계 h에 도달하면 경보입니다. p₀보다 낮은 관측은 누적치를 깎고, 높은 관측은 누적치를 올립니다. 경보 후에는 누적치를 초기화해 반복 경보 폭주를 막습니다. 계산은 과거와 현재 점수만 사용합니다.'''),
code('''def logit(p):\n    p=np.clip(np.asarray(p,dtype=float),1e-6,1-1e-6)\n    return np.log(p/(1-p))\n\ndef cusum_alarm_indices(prob, p0, h):\n    s=0.0; hits=[]\n    for i,x in enumerate(logit(prob)-logit(p0)):\n        s=max(0.0,s+x)\n        if s>=h:\n            hits.append(i); s=0.0\n    return np.asarray(hits,dtype=int)\n\ndef threshold_alarm_indices(prob, threshold, persistence=2):\n    x=np.asarray(prob)>=threshold\n    if len(x)<persistence:return np.array([],dtype=int)\n    return np.flatnonzero(np.convolve(x,np.ones(persistence,dtype=int),'valid')==persistence)+persistence-1\n'''),
md('''## 2. 먼저 전체 정상 리플레이에서 기준 조정\n\nCUSUM은 p₀와 h를 함께 정해야 합니다. 정상 구간의 점수 분포와 시간 순서를 보존해 후보를 비교하고, 기존 확정 경보의 정상 오경보율(약 0.96건/24시간) 이하인 조합을 선택합니다. 이 재생 자료는 정책 조정 자료이므로 결과를 독립 검증치로 부르지 않습니다.'''),
code('''# 각 reactor의 정상 구간을 연속 segment로 유지\nsegments=[]\nfor _,g in full.groupby('reactor_id',sort=False):\n    g=g.sort_values('timestamp').reset_index(drop=True)\n    normal=g.fault_type.eq(0)\n    seg=normal.ne(normal.shift(fill_value=normal.iloc[0])).cumsum()\n    segments.extend(x.current_probability.to_numpy() for _,x in g[normal].groupby(seg[normal]))\nnormal_minutes=sum(map(len,segments)); baseline_rate=0.9565\nrows=[]\nfor p0 in [.01,.02,.03,.05,.075,.10,.15,.20]:\n  for h in [.5,1,1.5,2,3,4,6,8,10,12,16,20,25,30]:\n    alarms=sum(len(cusum_alarm_indices(x,p0,h)) for x in segments)\n    rate=alarms/(normal_minutes/1440)\n    rows.append((p0,h,alarms,rate))\ncal=pd.DataFrame(rows,columns=['reference_probability','boundary_h','normal_alerts','alerts_per_24h'])\nfeasible=cal[cal.alerts_per_24h<=baseline_rate].sort_values(['boundary_h','reference_probability'])\nprint('기존 확정 경보 기준 오경보율:',baseline_rate,'/24h')\nprint(feasible.head(12).to_string(index=False))\n'''),
md('''## 3. Test 이벤트별 지연 비교\n\n파라미터를 Test 결과를 보고 고르지 않습니다. 각 이벤트의 결함 구간에서 첫 경보가 나온 시점을 지연으로 계산하고, 같은 선택 파라미터의 전체 Test 이벤트 탐지율과 중앙 지연을 보고합니다. CUSUM 경보는 오경보 뒤 누적치가 초기화되므로 이벤트 진입 직전 정상 구간에서 이어지는 누적도 반영합니다.'''),
code('''# 기존 threshold 방식과 calibration에서 선택한 CUSUM 조합을 나란히 계산\nselected=feasible.iloc[0] if len(feasible) else None\nprint('선택 조합:',None if selected is None else selected.to_dict())\nrows=[]\nfor eid,g in test.groupby('sample_event_id'):\n    g=g.sort_values('relative_min').reset_index(drop=True)\n    fault_pos=np.flatnonzero(g.is_fault.to_numpy()==1)\n    if not len(fault_pos): continue\n    start=fault_pos[0]; fault_type=int(g.fault_type.iloc[start]); regime=g.operating_regime.iloc[start]\n    for name,idx in [('HGB threshold',threshold_alarm_indices(g.probability,.45,2))]:\n        after=idx[idx>=start]; delay=int(g.relative_min.iloc[after[0]]) if len(after) else np.nan\n        rows.append((name,eid,fault_type,regime,delay))\n    if selected is not None:\n        idx=cusum_alarm_indices(g.probability,selected.reference_probability,selected.boundary_h)\n        after=idx[idx>=start]; delay=int(g.relative_min.iloc[after[0]]) if len(after) else np.nan\n        rows.append(('CUSUM',eid,fault_type,regime,delay))\ndelays=pd.DataFrame(rows,columns=['method','event_id','fault_type','regime','delay_min'])\nprint(delays.groupby('method').delay_min.agg(['count','median','min','max']).to_string())\nprint('이벤트별 결과\\n',delays.pivot(index='event_id',columns='method',values='delay_min').to_string())\n'''),
md('''## 4. 결과 해석과 한계\n\nCUSUM이 중앙 지연을 낮추더라도 정상 오경보 제약을 넘으면 운영 후보로 채택하지 않습니다. Test는 독립 이벤트 8개뿐이므로 이벤트별 편차와 결함 유형·레짐별 결과를 함께 봅니다. CUSUM은 점수의 시간적 연속성을 활용하는 경보 규칙이지 새로 학습한 결함 모델이 아닙니다.\n\n결과를 본 뒤 파라미터를 다시 고르면 Test 누수가 되므로, 후속 조정은 validation 또는 새 기간 데이터에서 해야 합니다.'''),
code('''if len(delays):\n    summary=delays.groupby('method').agg(events=('event_id','nunique'),detected=('delay_min','count'),median_delay_min=('delay_min','median'))\n    print(summary.to_string())\n    print('\\n결함 유형별 중앙 지연\\n',delays.groupby(['method','fault_type']).delay_min.median().unstack(0).to_string())\n    delays.to_csv('data/modeling/test_cusum_delays.csv',index=False)\n    if selected is not None:\n        cfg={'model_file':'models/binary_fault_detector_hgb_optimized.joblib','model_unchanged':True,\n             'method':'one-sided CUSUM on HGB log-odds','reference_probability':float(selected.reference_probability),\n             'boundary_h':float(selected.boundary_h),'normal_alerts_per_24h_full_replay':float(selected.alerts_per_24h),\n             'test_median_delay_min':float(delays[delays.method.eq('CUSUM')].delay_min.median()),\n             'note':'Calibration uses continuous replay; independent test has 8 events.'}\n        Path('models/cusum_alarm_config.json').write_text(json.dumps(cfg,ensure_ascii=False,indent=2))\n''')]
nb={'cells':cells,'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3'}},'nbformat':4,'nbformat_minor':5}
